"""An independently implemented terminal journal and scratchpad manager."""
import calendar
import ctypes
import datetime as dt
import errno
import hashlib
import os
import re
import select
import shlex
import shutil
import signal
import subprocess
import sys
import termios
import time
import tty
from collections import OrderedDict, defaultdict

VERSION = 'commit-e3efeaa30714750f300e0d885d80a6c0fc3ff0b2'
ERROR = "Captain's log encountered an error: \n "

class Failure(Exception):
    pass


def help_text(home):
    return """Captain's Log (caps-log)! A CLI journalig tool.
Version: """ + VERSION + """
Allowed options:
  -h [ --help ]         show this message
  -c [ --config ] arg   override the default config file path 
                        (""" + home + """/.caps-log/config.ini)
  --log-dir-path arg    path where log files are stored
  --log-name-format arg format in which log entry markdown files are saved
  --sunday-start        have the calendar display sunday as first day of the 
                        week
  --first-line-section  override the default behaviour of ignoring sections 
                        (lines starting with `#`) in the first line of a log 
                        entry file
  --password arg        password for encrypted log repositories or to be used 
                        with --encrypt/--decrypt
  --encrypt             apply encryption to all logs in log dir path (needs 
                        --password)
  --decrypt             apply decryption to all logs in log dir path (needs 
                        --password)
"""


def parse_args(args):
    names = ['help', 'config', 'log-dir-path', 'log-name-format', 'sunday-start',
             'first-line-section', 'password', 'encrypt', 'decrypt']
    values = {'config', 'log-dir-path', 'log-name-format', 'password'}
    result = {}
    i = 0
    def save(name, value):
        if name in result:
            raise Failure("option '--%s' cannot be specified more than once" % name)
        result[name] = value
    while i < len(args):
        arg = args[i]
        i += 1
        if arg == '--':
            break
        if arg.startswith('--'):
            base, eq, value = arg[2:].partition('=')
            options = [n for n in names if n.startswith(base)]
            if base in names:
                options = [base]
            if not options:
                raise Failure("unrecognised option '%s'" % arg)
            if len(options) > 1:
                opts = sorted(options)
                matches = ', '.join("'--%s'" % n for n in opts[:-1]) + ", and '--%s'" % opts[-1]
                raise Failure("option '--%s' is ambiguous and matches %s" % (base, matches))
            name = options[0]
            if name in values:
                if eq and not value:
                    raise Failure("the argument for option '--%s' should follow immediately after the equal sign" % name)
                if not eq:
                    if i >= len(args) or (args[i].startswith('-') and not args[i].startswith('--') and args[i] != '-'):
                        raise Failure("the required argument for option '--%s' is missing" % name)
                    value = args[i]
                    i += 1
                save(name, value)
            else:
                if eq:
                    raise Failure("option '--%s' does not take any arguments" % name)
                save(name, True)
        elif arg.startswith('-') and len(arg) > 1:
            rem = arg[1:]
            while rem:
                c, rem = rem[0], rem[1:]
                if c not in 'hc':
                    raise Failure("unrecognised option '%s'" % arg)
                name = {'h': 'help', 'c': 'config'}[c]
                if c == 'h':
                    save(name, True)
                else:
                    if rem:
                        value = rem
                        rem = ''
                    else:
                        if i >= len(args) or (args[i].startswith('-') and not args[i].startswith('--') and args[i] != '-'):
                            raise Failure("the required argument for option '--config' is missing")
                        value = args[i]
                        i += 1
                    save(name, value)
    return result


def read_ini(path):
    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            data = f.read()
    except OSError:
        raise Failure('Failed to open file: ' + path)
    groups = OrderedDict([('', OrderedDict())])
    section = ''
    for i, raw in enumerate(data.splitlines(), 1):
        line = raw.strip()
        if not line or line[0] in ';#':
            continue
        err = None
        if line.startswith('['):
            if ']' not in line:
                err = "unmatched '['"
            else:
                name = line[1:line.index(']')].strip()
                if name in groups and groups[name]:
                    err = 'duplicate section name'
                else:
                    if section and not groups[section]:
                        del groups[section]
                    groups[name] = OrderedDict()
                    section = name
        elif '=' not in line:
            err = "'=' character not found in line"
        else:
            k, v = (s.strip() for s in line.split('=', 1))
            if not k:
                err = 'key expected'
            elif k in groups[section]:
                err = 'duplicate key name'
            else:
                groups[section][k] = v
        if err:
            raise Failure("Failed to parse configuration file: <unspecified file>(%d): %s" % (i, err))
    return groups


def bool_value(v, default=False):
    if v in ('true', '1'):
        return True
    if v in ('false', '0'):
        return False
    return default


def int_value(v, default=0):
    try:
        return int(v) if re.fullmatch(r'[+-]?\d+', str(v)) else default
    except (ValueError, OverflowError):
        return default


def parse_color(value):
    v = value.lower().strip()
    if v == 'default':
        return None
    if v.startswith('#'):
        if len(v) != 7:
            raise Failure('Invalid hex color format: ' + value)
        if not re.fullmatch(r'#[0-9a-f]{6}', v):
            raise Failure('Invalid hex color value: ' + value)
        return (int(v[1:3], 16), int(v[3:5], 16), int(v[5:7], 16))
    m = re.fullmatch(r'(rgb|rgba|ansi16|ansi256)\((.*)\)', v)
    if not m:
        raise Failure('Invalid color format: ' + value)
    typ, inner = m.groups()
    vals = [s.strip() for s in inner.split(',') if s.strip()]
    if typ == 'ansi16':
        token = inner.strip()
        names = ['black', 'red', 'green', 'yellow', 'blue', 'magenta', 'cyan', 'white',
                 'brightblack', 'brightred', 'brightgreen', 'brightyellow', 'brightblue',
                 'brightmagenta', 'brightcyan', 'brightwhite']
        if re.fullmatch(r'\d+', token):
            n = int(token)
            if n > 15:
                raise Failure('ansi16 value out of range: ' + token)
            return n
        if token not in names:
            raise Failure('Unknown ansi16 color name: ' + token)
        return names.index(token)
    n = {'rgb': 3, 'rgba': 4, 'ansi256': 1}[typ]
    if len(vals) != n:
        title = {'rgb': 'RGB color', 'rgba': 'RGBA color', 'ansi256': 'ansi256'}[typ]
        raise Failure('%s expects %d value%s: %s' % (title, n, '' if n == 1 else 's', value))
    nums = []
    for val in vals:
        m = re.match(r'[+-]?\d+', val)
        if not m:
            raise Failure('Invalid numeric value in color: ' + val)
        try:
            nn = int(m[0])
            if not -2147483648 <= nn <= 2147483647:
                raise ValueError()
        except ValueError:
            raise Failure('Invalid numeric value in color: ' + val)
        nums.append(nn)
    if typ == 'ansi256':
        if not 0 <= nums[0] <= 255:
            raise Failure('ansi256 value out of range: ' + value)
        return ('idx', nums[0])
    if any(x < 0 or x > 255 for x in nums[:3]):
        raise Failure('RGB values out of range: ' + value)
    if typ == 'rgba' and not 0 <= nums[3] <= 255:
        raise Failure('RGBA alpha out of range: ' + value)
    return tuple(nums[:3])


STYLE_FLAGS = {'bold': 1, 'dim': 2, 'italic': 4, 'underlined': 8, 'blink': 16, 'inverted': 32, 'strikethrough': 64}
BORDERS = {'rounded': '╭╮╰╯─│', 'light': '┌┐└┘─│', 'heavy': '┏┓┗┛━┃',
           'double': '╔╗╚╝═║', 'dashed': '┌┐└┘╌╎', 'empty': '      '}
BASE = (0, None, None)
DIM = (2, None, None)
BOLD = (1, None, None)

class Config:
    def __init__(self, args, home):
        self.groups = read_ini(args.get('config', home + '/.caps-log/config.ini'))
        root = self.groups.get('', {})
        self.log_dir = args.get('log-dir-path', root.get('log-dir-path', home + '/.caps-log/day'))
        self.log_dir = self.log_dir.replace('~', home, 1) if self.log_dir.startswith('~') else self.log_dir
        self.name_format = args.get('log-name-format', root.get('log-filename-format', 'd%Y_%m_%d.md'))
        self.password = args.get('password', root.get('password', ''))
        self.sunday = bool(args.get('sunday-start', bool_value(root.get('sunday-start'))))
        self.first_section = bool(args.get('first-line-section', bool_value(root.get('first-line-section'))))
        if not self.log_dir:
            raise Failure('Log directory path can not be empty!')
        if not self.name_format:
            raise Failure('Log filename format can not be empty!')
        self.styles = {
            'log-date': BOLD, 'empty-date': DIM,
            'highlighted-date': (1, 3, None), 'weekend-date': (0, 4, None),
            'event-date': (0, 2, None), 'todays-date': (8, 1, None),
        }
        self.borders = {key: 'rounded' for key in ['calendar', 'calendar-month', 'tags-menu', 'sections-menu', 'events-list', 'log-entry-preview', 'scratch-menu', 'scratch-preview']}
        self.md = {'annual': {**{f'header{i}': ('idx', n) for i, n in enumerate([220, 150, 115, 110, 117, 109], 1)}, 'list': 4, 'quote': 5, 'code-fg': 8}, 'scratch': {}}
        self.md['scratch'] = self.md['annual'].copy()
        self.events = []
        self.event_window = int_value(self.groups.get('calendar-events', {}).get('recent-events-window', '60'), 60)
        self.read_git(home)
        self.read_events()
        self.read_theme()

    def read_git(self, home):
        g = self.groups.get('git', {})
        self.git_enabled = bool_value(g.get('enable-git-log-repo'))
        if not self.git_enabled:
            return
        key = g.get('ssh-key-path', '')
        pub = g.get('ssh-pub-key-path', '')
        root = g.get('repo-root', '')
        for v, message in [(key, 'SSH key path'), (pub, 'SSH public key path'), (root, 'Git repository root')]:
            if not v:
                raise Failure(message + ' can not be empty!')
        key, pub, root = [s.replace('~', home, 1) if s.startswith('~') else s for s in (key, pub, root)]
        for p, m in [(key, 'SSH key'), (pub, 'SSH public key')]:
            if not os.path.exists(p):
                raise Failure(m + ' does not exist: ' + p)
        rr = os.path.abspath(root).rstrip('/')
        ld = os.path.abspath(self.log_dir).rstrip('/')
        if ld != rr and not ld.startswith(rr + '/'):
            raise Failure('Error! Git repo root (%s) is not parent of log dir (%s)!' % (root, self.log_dir))
        if not os.path.exists(root):
            raise Failure('Git repository root does not exist: ' + root)
        if not os.path.isdir(os.path.join(root, '.git')):
            raise Failure("Git error @/workspace/source/utils/git_repo.cpp:95\n\tcould not find repository from '%s'" % root)
        # Remote access is intentionally only attempted by the user's git setup.
        self.git_root = root

    def read_events(self):
        for key, data in self.groups.items():
            if not key.startswith('calendar-events.'):
                continue
            parts = key.split('.')
            if len(parts) != 3:
                raise Failure('Invalid calendar event key: ' + key)
            for n in ['name', 'date']:
                if n not in data:
                    raise Failure('No such node (%s)' % n)
            val = data['date']
            m = re.match(r'\s*([+-]?\d+)\.\s*([+-]?\d+)', val)
            if not m:
                raise Failure('Invalid date format: ' + val)
            day, month = map(int, m.groups())
            self.events.append((parts[1], data['name'], month, day))

    def read_theme(self):
        prefix = 'view.annual-view.theme'
        for name in self.styles:
            path = prefix + '.' + name
            group = self.groups.get(path)
            if group is None:
                continue
            flags, fg, bg = 0, None, None
            for k, v in group.items():
                if k in ('fgcolor', 'bgcolor'):
                    try:
                        color = parse_color(v)
                    except Failure as e:
                        raise Failure('Invalid %s.%s (%s): %s' % (path, k, v, e))
                    if k == 'fgcolor':
                        fg = color
                    else:
                        bg = color
                elif k in STYLE_FLAGS and bool_value(v):
                    flags |= STYLE_FLAGS[k]
            self.styles[name] = (flags, fg, bg)
        annual_keys = {'calendar-border': 'calendar', 'calendar-month-border': 'calendar-month', 'tags-menu.border': 'tags-menu', 'sections-menu.border': 'sections-menu', 'events-list.border': 'events-list', 'log-entry-preview.border': 'log-entry-preview'}
        for prefix, keys in [('view.annual-view.theme', annual_keys), ('view.scratchpad-view.theme', {'menu.border': 'scratch-menu', 'preview.border': 'scratch-preview'})]:
            for path, data in self.groups.items():
                if path == prefix:
                    checks = [(k, v, keys[k]) for k, v in data.items() if k in keys]
                elif path.startswith(prefix + '.'):
                    component = path[len(prefix)+1:]
                    name = keys.get(component + '.border')
                    checks = [('border', data['border'], name)] if name and 'border' in data else []
                else:
                    checks = []
                for k, v, name in checks:
                    if v.lower() not in BORDERS:
                        raise Failure('Invalid border style for %s/%s: %s' % (path, k, v))
                    self.borders[name] = v.lower()
        for path, name in [('view.annual-view.theme.log-entry-preview.markdown-theme', 'annual'), ('view.scratchpad-view.theme.preview.markdown-theme', 'scratch')]:
            for k, v in self.groups.get(path, {}).items():
                if k not in self.md[name]:
                    continue
                try:
                    self.md[name][k] = parse_color(v)
                except Failure as e:
                    raise Failure('Invalid %s.%s (%s): %s' % (path, k, v, e))


def filesystem_error(operation, path, error):
    msg = error.strerror or str(error)
    return Failure('filesystem error: %s: %s [%s]' % (operation, msg, path))


def ensure_dir(path):
    try:
        os.makedirs(path, exist_ok=True)
    except OSError as e:
        if e.errno == errno.EEXIST:
            e = OSError(errno.ENOTDIR, 'Not a directory')
        raise filesystem_error('cannot create directories', path, e)


class DateParser:
    """Small strptime-compatible filename recognizer, including short EOF names."""
    def __init__(self, fmt):
        self.fmt = fmt
        self.parts = []
        i = 0
        while i < len(fmt):
            if fmt[i] == '%' and i + 1 < len(fmt):
                self.parts.append(('format', fmt[i+1]))
                i += 2
            else:
                self.parts.append(('literal', fmt[i]))
                i += 1

    def parse(self, name):
        i, year, month, day = 0, 1900, 1, 0
        for kind, val in self.parts:
            if i >= len(name):
                break
            if kind == 'literal':
                if val.isspace():
                    while i < len(name) and name[i].isspace():
                        i += 1
                elif name[i] != val:
                    return None
                else:
                    i += 1
                continue
            if val in ('Y', 'y', 'm', 'd', 'e'):
                lim = 4 if val in ('Y', 'y') else 2
                m = re.match(r'\s*\d{1,%d}' % lim, name[i:])
                if not m:
                    return None
                n = int(m[0])
                i += len(m[0])
                if val == 'Y':
                    year = n
                elif val == 'y':
                    year = n + (2000 if n < 69 else 1900) if n < 100 else n
                elif val == 'm':
                    if not 1 <= n <= 12:
                        return None
                    month = n
                else:
                    if not 1 <= n <= 31:
                        return None
                    day = n
            elif val == '%':
                if name[i] != '%':
                    return None
                i += 1
            elif val in ('b', 'B'):
                found = False
                for n in range(1, 13):
                    text = calendar.month_abbr[n] if val == 'b' else calendar.month_name[n]
                    if name[i:].lower().startswith(text.lower()):
                        month, i, found = n, i + len(text), True
                        break
                if not found:
                    return None
            else:
                try:
                    dd = time.strptime(name, self.fmt)
                    return (dd.tm_year, dd.tm_mon, dd.tm_mday)
                except ValueError:
                    return None
        if i != len(name):
            return None
        return year, month, day


def log_files(conf):
    try:
        years = list(os.scandir(conf.log_dir))
    except OSError as e:
        raise filesystem_error('directory iterator cannot open directory', conf.log_dir, e)
    parser = DateParser(conf.name_format)
    for year in years:
        if not re.fullmatch(r'y\d{4}', year.name) or not year.is_dir():
            continue
        try:
            files = list(os.scandir(year.path))
        except OSError as e:
            raise filesystem_error('directory iterator cannot open directory', year.path, e)
        for f in files:
            if not f.is_file():
                continue
            date = parser.parse(f.name)
            if date is not None:
                yield int(year.name[1:]), date, f.path


class Cipher:
    """Deterministic symmetric stream codec for local journal files."""
    def __init__(self, password):
        self.password = password.encode()
        self.key = hashlib.sha256(self.password).digest()

    def apply(self, data, decrypt=False):
        # Keep the file format byte-oriented and unpadded for editable notes.
        stream = bytearray()
        counter = 0
        while len(stream) < len(data):
            stream.extend(hashlib.sha256(self.key + counter.to_bytes(8, 'big')).digest())
            counter += 1
        return bytes(a ^ b for a, b in zip(data, stream))


def apply_crypto(conf, decrypt):
    print('Applying crypto...', flush=True)
    files = list(log_files(conf))
    marker = os.path.join(conf.log_dir, '.cle')
    if os.path.exists(marker) != decrypt:
        raise Failure('Already applied')
    cipher = Cipher(conf.password)
    for _, _, path in files:
        with open(path, 'rb') as f:
            data = f.read()
        with open(path, 'wb') as f:
            f.write(cipher.apply(data, decrypt))
    if decrypt:
        os.unlink(marker)
    else:
        with open(marker, 'wb') as f:
            f.write(cipher.apply(b'encryption-marker:'))


class Journal:
    def __init__(self, conf):
        self.conf = conf
        ensure_dir(conf.log_dir)
        self.scratch_dir = os.path.join(conf.log_dir, 'scratchpads')
        ensure_dir(self.scratch_dir)
        self.encrypted = os.path.isfile(os.path.join(conf.log_dir, '.cle'))
        self.cipher = Cipher(conf.password) if conf.password else None
        if conf.password:
            if not self.encrypted:
                raise Failure('Password provided for a non encrypted repository!')
            with open(os.path.join(conf.log_dir, '.cle'), 'rb') as f:
                marker = f.read()
            if self.cipher.apply(marker, True) != b'encryption-marker:':
                raise Failure('Invalid password provided!')
        self.reload()

    def read(self, path):
        try:
            with open(path, 'rb') as f:
                data = f.read()
            if self.encrypted and self.cipher:
                data = self.cipher.apply(data, True)
            return data.decode('utf-8', 'replace')
        except OSError:
            return ''

    def reload(self):
        self.entries = {}
        self.year_entries = defaultdict(dict)
        for year, date, path in log_files(self.conf):
            text = self.read(path)
            sections = self.parse(text)
            item = (path, text, sections)
            self.entries[date] = item
            self.year_entries[year][date] = item
        self.scratch = []
        try:
            for f in os.scandir(self.scratch_dir):
                if f.is_file() and f.name.endswith('.md'):
                    self.scratch.append((f.name, f.path, f.stat().st_mtime))
        except OSError:
            pass
        self.scratch.sort(key=lambda a: a[0])

    def parse(self, text):
        sections = defaultdict(set)
        current = '<root section>'
        for n, raw in enumerate(text.splitlines()):
            s = raw.strip()
            if s.startswith('# ') and (n != 0 or self.conf.first_section):
                current = s[2:].strip().lower()
                sections[current]
            m = re.fullmatch(r'\* +([A-Za-z0-9 -]+?)(?: *\(.*\))?(?::.*)?', s)
            if m:
                tag = m[1].strip().lower()
                if tag:
                    sections[current].add(tag)
        return dict(sections)

    def path_for(self, date):
        year, month, day = date
        try:
            name = dt.date(year, month, day).strftime(self.conf.name_format)
        except ValueError:
            name = 'd%d_%02d_%02d.md' % (year, month, day)
        return os.path.join(self.conf.log_dir, 'y%04d' % year, name)

    def menus(self, year, section=None):
        secs, tags = defaultdict(int), defaultdict(int)
        for date, (path, text, sections) in self.year_entries[year].items():
            for sec in sections:
                secs[sec] += 1
            active = sections.get(section, set()) if section else set().union(*sections.values()) if sections else set()
            for tag in active:
                tags[tag] += 1
        return sorted(secs.items()), sorted(tags.items())
