def parse_args(args):
    names = ['help', 'config', 'log-dir-path', 'log-name-format', 'sunday-start',
             'first-line-section', 'password', 'encrypt', 'decrypt']
    values = {'config', 'log-dir-path', 'log-name-format', 'password'}
    result = {}
    i = 0
    def save(name, value):
        if name in result:
            raise Failure("option '--%s' cannot be specified more than once" % name)
        result[name] = value
    while i < len(args):
        arg = args[i]
        i += 1
        if arg == '--':
            break
        if arg.startswith('--'):
            base, eq, value = arg[2:].partition('=')
            options = [n for n in names if n.startswith(base)]
            if base in names:
                options = [base]
            if not options:
                raise Failure("unrecognised option '%s'" % arg)
            if len(options) > 1:
                opts = sorted(options)
                matches = ', '.join("'--%s'" % n for n in opts[:-1]) + ", and '--%s'" % opts[-1]
                raise Failure("option '--%s' is ambiguous and matches %s" % (base, matches))
            name = options[0]
            if name in values:
                if eq and not value:
                    raise Failure("the argument for option '--%s' should follow immediately after the equal sign" % name)
                if not eq:
                    if i >= len(args) or (args[i].startswith('-') and not args[i].startswith('--') and args[i] != '-'):
                        raise Failure("the required argument for option '--%s' is missing" % name)
                    value = args[i]
                    i += 1
                save(name, value)
            else:
                if eq:
                    raise Failure("option '--%s' does not take any arguments" % name)
                save(name, True)
        elif arg.startswith('-') and len(arg) > 1:
            rem = arg[1:]
            while rem:
                c, rem = rem[0], rem[1:]
                if c not in 'hc':
                    raise Failure("unrecognised option '%s'" % arg)
                name = {'h': 'help', 'c': 'config'}[c]
                if c == 'h':
                    save(name, True)
                else:
                    if rem:
                        value = rem
                        rem = ''
                    else:
