                            raise Failure("the required argument for option '--config' is missing")
                        value = args[i]
                        i += 1
                    save(name, value)
    return result


def read_ini(path):
    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            data = f.read()
    except OSError:
        raise Failure('Failed to open file: ' + path)
    groups = OrderedDict([('', OrderedDict())])
    section = ''
    for i, raw in enumerate(data.splitlines(), 1):
        line = raw.strip()
        if not line or line[0] in ';#':
            continue
        err = None
        if line.startswith('['):
            if ']' not in line:
                err = "unmatched '['"
            else:
                name = line[1:line.index(']')].strip()
                if name in groups and groups[name]:
                    err = 'duplicate section name'
                else:
                    if section and not groups[section]:
                        del groups[section]
                    groups[name] = OrderedDict()
                    section = name
        elif '=' not in line:
            err = "'=' character not found in line"
        else:
            k, v = (s.strip() for s in line.split('=', 1))
            if not k:
                err = 'key expected'
            elif k in groups[section]:
                err = 'duplicate key name'
            else:
                groups[section][k] = v
        if err:
            raise Failure("Failed to parse configuration file: <unspecified file>(%d): %s" % (i, err))
    return groups


def bool_value(v, default=False):
    if v in ('true', '1'):
        return True
    if v in ('false', '0'):
        return False
    return default


def int_value(v, default=0):
    try:
        return int(v) if re.fullmatch(r'[+-]?\d+', str(v)) else default
    except (ValueError, OverflowError):
        return default


def parse_color(value):
    v = value.lower().strip()
    if v == 'default':
        return None
    if v.startswith('#'):
        if len(v) != 7:
            raise Failure('Invalid hex color format: ' + value)
        if not re.fullmatch(r'#[0-9a-f]{6}', v):
            raise Failure('Invalid hex color value: ' + value)
        return (int(v[1:3], 16), int(v[3:5], 16), int(v[5:7], 16))
    m = re.fullmatch(r'(rgb|rgba|ansi16|ansi256)\((.*)\)', v)
    if not m:
        raise Failure('Invalid color format: ' + value)
    typ, inner = m.groups()
    vals = [s.strip() for s in inner.split(',') if s.strip()]
    if typ == 'ansi16':
        token = inner.strip()
        names = ['black', 'red', 'green', 'yellow', 'blue', 'magenta', 'cyan', 'white',
                 'brightblack', 'brightred', 'brightgreen', 'brightyellow', 'brightblue',
                 'brightmagenta', 'brightcyan', 'brightwhite']
        if re.fullmatch(r'\d+', token):
            n = int(token)
            if n > 15:
                raise Failure('ansi16 value out of range: ' + token)
            return n
        if token not in names:
            raise Failure('Unknown ansi16 color name: ' + token)
        return names.index(token)
    n = {'rgb': 3, 'rgba': 4, 'ansi256': 1}[typ]
    if len(vals) != n:
        title = {'rgb': 'RGB color', 'rgba': 'RGBA color', 'ansi256': 'ansi256'}[typ]
        raise Failure('%s expects %d value%s: %s' % (title, n, '' if n == 1 else 's', value))
    nums = []
    for val in vals:
        m = re.match(r'[+-]?\d+', val)
        if not m:
            raise Failure('Invalid numeric value in color: ' + val)
        try:
            nn = int(m[0])
            if not -2147483648 <= nn <= 2147483647:
                raise ValueError()
        except ValueError:
            raise Failure('Invalid numeric value in color: ' + val)
        nums.append(nn)
    if typ == 'ansi256':
        if not 0 <= nums[0] <= 255:
            raise Failure('ansi256 value out of range: ' + value)
        return ('idx', nums[0])
    if any(x < 0 or x > 255 for x in nums[:3]):
        raise Failure('RGB values out of range: ' + value)
    if typ == 'rgba' and not 0 <= nums[3] <= 255:
        raise Failure('RGBA alpha out of range: ' + value)
    return tuple(nums[:3])


