    def read_git(self, home):
        g = self.groups.get('git', {})
        self.git_enabled = bool_value(g.get('enable-git-log-repo'))
        if not self.git_enabled:
            return
        key = g.get('ssh-key-path', '')
        pub = g.get('ssh-pub-key-path', '')
        root = g.get('repo-root', '')
        for v, message in [(key, 'SSH key path'), (pub, 'SSH public key path'), (root, 'Git repository root')]:
            if not v:
                raise Failure(message + ' can not be empty!')
        key, pub, root = [s.replace('~', home, 1) if s.startswith('~') else s for s in (key, pub, root)]
        for p, m in [(key, 'SSH key'), (pub, 'SSH public key')]:
            if not os.path.exists(p):
                raise Failure(m + ' does not exist: ' + p)
        rr = os.path.abspath(root).rstrip('/')
        ld = os.path.abspath(self.log_dir).rstrip('/')
        if ld != rr and not ld.startswith(rr + '/'):
            raise Failure('Error! Git repo root (%s) is not parent of log dir (%s)!' % (root, self.log_dir))
        if not os.path.exists(root):
            raise Failure('Git repository root does not exist: ' + root)
        if not os.path.isdir(os.path.join(root, '.git')):
            raise Failure("Git error @/workspace/source/utils/git_repo.cpp:95\n\tcould not find repository from '%s'" % root)
        # Remote access is intentionally only attempted by the user's git setup.
