    def read_events(self):
        for key, data in self.groups.items():
            if not key.startswith('calendar-events.'):
                continue
            parts = key.split('.')
            if len(parts) != 3:
                raise Failure('Invalid calendar event key: ' + key)
            for n in ['name', 'date']:
                if n not in data:
                    raise Failure('No such node (%s)' % n)
            val = data['date']
            m = re.match(r'\s*([+-]?\d+)\.\s*([+-]?\d+)', val)
            if not m:
                raise Failure('Invalid date format: ' + val)
            day, month = map(int, m.groups())
            self.events.append((parts[1], data['name'], month, day))

    def read_theme(self):
        prefix = 'view.annual-view.theme'
        for name in self.styles:
            path = prefix + '.' + name
            group = self.groups.get(path)
            if group is None:
                continue
            flags, fg, bg = 0, None, None
            for k, v in group.items():
                if k in ('fgcolor', 'bgcolor'):
                    try:
                        color = parse_color(v)
                    except Failure as e:
                        raise Failure('Invalid %s.%s (%s): %s' % (path, k, v, e))
                    if k == 'fgcolor':
                        fg = color
                    else:
                        bg = color
                elif k in STYLE_FLAGS and bool_value(v):
                    flags |= STYLE_FLAGS[k]
            self.styles[name] = (flags, fg, bg)
        annual_keys = {'calendar-border': 'calendar', 'calendar-month-border': 'calendar-month', 'tags-menu.border': 'tags-menu', 'sections-menu.border': 'sections-menu', 'events-list.border': 'events-list', 'log-entry-preview.border': 'log-entry-preview'}
        for prefix, keys in [('view.annual-view.theme', annual_keys), ('view.scratchpad-view.theme', {'menu.border': 'scratch-menu', 'preview.border': 'scratch-preview'})]:
            for path, data in self.groups.items():
                if path == prefix:
                    checks = [(k, v, keys[k]) for k, v in data.items() if k in keys]
                elif path.startswith(prefix + '.'):
                    component = path[len(prefix)+1:]
                    name = keys.get(component + '.border')
                    checks = [('border', data['border'], name)] if name and 'border' in data else []
                else:
                    checks = []
                for k, v, name in checks:
                    if v.lower() not in BORDERS:
                        raise Failure('Invalid border style for %s/%s: %s' % (path, k, v))
                    self.borders[name] = v.lower()
        for path, name in [('view.annual-view.theme.log-entry-preview.markdown-theme', 'annual'), ('view.scratchpad-view.theme.preview.markdown-theme', 'scratch')]:
            for k, v in self.groups.get(path, {}).items():
                if k not in self.md[name]:
                    continue
                try:
                    self.md[name][k] = parse_color(v)
                except Failure as e:
                    raise Failure('Invalid %s.%s (%s): %s' % (path, k, v, e))


def filesystem_error(operation, path, error):
