        sys.stdout.flush()

    def key(self, timeout=.15):
        if not self.buffer:
            if not select.select([0], [], [], timeout)[0]:
                return None
            data = os.read(0, 4096)
            if not data:
                time.sleep(timeout)
                return None
            self.buffer += data
        if self.buffer.startswith(b'\x1b'):
            if self.buffer == b'\x1b' and select.select([0], [], [], .025)[0]:
                self.buffer += os.read(0, 4096)
            seqs = {b'\x1b[A':'up',b'\x1b[B':'down',b'\x1b[C':'right',b'\x1b[D':'left',b'\x1b[Z':'backtab',
                    b'\x1bOP':'f1',b'\x1b[11~':'f1',b'\x1b[1~':'home',b'\x1b[4~':'end',b'\x1b[H':'home',b'\x1b[F':'end',
                    b'\x1b[5~':'pageup',b'\x1b[6~':'pagedown',b'\x1b[3~':'delete',b'\x1bOA':'up',b'\x1bOB':'down',b'\x1bOC':'right',b'\x1bOD':'left'}
            for seq, name in seqs.items():
                if self.buffer.startswith(seq):
                    self.buffer = self.buffer[len(seq):]
                    return name
            mouse = re.match(rb'\x1b\[<(\d+);(\d+);(\d+)([Mm])', self.buffer)
            if mouse:
                self.buffer = self.buffer[mouse.end():]
                return ('mouse', int(mouse[1]), int(mouse[2])-1, int(mouse[3])-1, mouse[4] == b'M')
            other = re.match(rb'\x1b\[[0-9;?]*[a-zA-Z~]', self.buffer)
            if other:
                self.buffer = self.buffer[other.end():]
                return None
            self.buffer = self.buffer[1:]
            return 'escape'
        ch = self.buffer[0]
        if ch >= 128:
            n = 2 if ch < 224 else 3 if ch < 240 else 4
            text = self.buffer[:n].decode('utf-8', 'replace')
            self.buffer = self.buffer[n:]
            return text
        self.buffer = self.buffer[1:]
        return {3:'ctrlc',4:'ctrld',9:'tab',13:'enter',10:'enter',127:'backspace',8:'backspace'}.get(ch, chr(ch))


