def styled(base, more):
    return (base[0] | more[0], more[1] if more[1] is not None else base[1], more[2] if more[2] is not None else base[2])


class Canvas:
    def __init__(self, width, height):
        self.width, self.height = max(0, width), max(0, height)
        self.cells = [[[' ', BASE] for _ in range(self.width)] for _ in range(self.height)]

    def put(self, x, y, char, style=BASE):
        if 0 <= x < self.width and 0 <= y < self.height:
            self.cells[y][x] = [char, style]

    def text(self, x, y, text, style=BASE, width=None):
        if width is not None:
            text = text[:max(0, width)]
        for ch in text:
            if ch == '\t':
                ch = ' '
            if ord(ch) < 32:
                ch = ' '
            self.put(x, y, ch, style)
            x += 1

    def fill(self, x, y, w, h, char=' ', style=BASE):
        for j in range(max(0, y), min(y+h, self.height)):
            for i in range(max(0, x), min(x+w, self.width)):
                self.cells[j][i] = [char, style]

    def border(self, x, y, w, h, label='', kind='rounded', style=BASE, clear=False):
        if w < 2 or h < 2:
            return
        if clear:
            self.fill(x, y, w, h, style=style)
        tl, tr, bl, br, hor, ver = BORDERS.get(kind, BORDERS['rounded'])
        for i in range(x+1, x+w-1):
            self.put(i, y, hor, style)
            self.put(i, y+h-1, hor, style)
        for j in range(y+1, y+h-1):
            self.put(x, j, ver, style)
            self.put(x+w-1, j, ver, style)
        for i, j, c in [(x,y,tl),(x+w-1,y,tr),(x,y+h-1,bl),(x+w-1,y+h-1,br)]:
            self.put(i, j, c, style)
        self.text(x+1, y, label, style, w-2)

    def copy(self, other, x, y, sx=0, sy=0, w=None, h=None):
        w = other.width-sx if w is None else w
        h = other.height-sy if h is None else h
        for j in range(h):
            for i in range(w):
                if 0 <= sy+j < other.height and 0 <= sx+i < other.width:
                    ch, style = other.cells[sy+j][sx+i]
                    self.put(x+i, y+j, ch, style)

    def centered(self, x, y, w, text, style=BASE):
        self.text(x+max(0, (w-len(text))//2), y, text, style, w)

    def connect(self):
        # Terminal box drawings join where clipped panels or modal edges meet.
        bits = {'─': 3, '│': 12, '┌': 10, '┐': 9, '└': 6, '┘': 5, '╭': 10, '╮': 9, '╰': 6, '╯': 5,
                '├': 14, '┤': 13, '┬': 11, '┴': 7, '┼': 15,
                '━': 3, '┃': 12, '┏': 10, '┓': 9, '┗': 6, '┛': 5, '┣': 14, '┫': 13, '┳': 11, '┻': 7, '╋': 15,
                '═': 3, '║': 12, '╔': 10, '╗': 9, '╚': 6, '╝': 5, '╠': 14, '╣': 13, '╦': 11, '╩': 7, '╬': 15,
                '╌': 3, '╎': 12}
        lines = {3:'─',12:'│',10:'┌',9:'┐',6:'└',5:'┘',14:'├',13:'┤',11:'┬',7:'┴',15:'┼'}
        for y in range(self.height):
            for x in range(self.width):
                ch = self.cells[y][x][0]
                if ch not in bits:
                    continue
                b = bits[ch]
                # Joining a perpendicular neighboring line is enough; never extend text.
                for dx, dy, outbit, inbit in [(-1,0,1,2),(1,0,2,1),(0,-1,4,8),(0,1,8,4)]:
                    xx, yy = x+dx, y+dy
                    if 0 <= xx < self.width and 0 <= yy < self.height:
                        n = bits.get(self.cells[yy][xx][0], 0)
                        if n & inbit:
                            b |= outbit
                if b != bits[ch] and b in lines:
                    replacement = lines[b]
                    if ch in '━┃┏┓┗┛┣┫┳┻╋':
                        replacement = dict(zip('─│┌┐└┘├┤┬┴┼','━┃┏┓┗┛┣┫┳┻╋'))[replacement]
                    if ch in '═║╔╗╚╝╠╣╦╩╬':
                        replacement = dict(zip('─│┌┐└┘├┤┬┴┼','═║╔╗╚╝╠╣╦╩╬'))[replacement]
                    self.cells[y][x][0] = replacement


def color_code(c, background=False):
    if c is None:
        return []
    if isinstance(c, int):
        return [str((40 if background else 30) + c)] if c < 8 else [str((100 if background else 90) + c-8)]
    if c[0] == 'idx':
        return [str(48 if background else 38), '5', str(c[1])]
    return [str(48 if background else 38), '2', *map(str, c)]


def escape_style(style):
    flags, fg, bg = style
    codes = ['0']
    for bit, code in [(1,1),(2,2),(4,3),(8,4),(16,5),(32,7),(64,9)]:
        if flags & bit:
            codes.append(str(code))
    codes += color_code(fg) + color_code(bg, True)
    return '\x1b[' + ';'.join(codes) + 'm'


class Terminal:
    def __init__(self):
        self.old = None
        self.active = False
        self.resized = True
        self.buffer = b''

    def size(self):
        try:
            s = os.get_terminal_size(1)
            return s.columns, s.lines
        except OSError:
            return 80, 24

    def start(self):
        if self.active:
            return
        if os.isatty(0):
            try:
                self.old = termios.tcgetattr(0)
                tty.setraw(0)
            except termios.error:
                pass
        self.active = True
        sys.stdout.write('\x1b[?1049h\x1b[?7l\x1b[?25l\x1b[?1000h\x1b[?1003h\x1b[?1015h\x1b[?1006h')
        sys.stdout.flush()

    def stop(self):
        if not self.active:
            return
        sys.stdout.write('\x1b[0m\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1000l\x1b[?25h\x1b[?7h\x1b[?1049l')
        sys.stdout.flush()
        if self.old is not None:
            try:
                termios.tcsetattr(0, termios.TCSADRAIN, self.old)
            except termios.error:
                pass
        self.active = False

    def draw(self, canvas):
        canvas.connect()
        pieces = ['\x1b[H']
        previous = None
        for y, row in enumerate(canvas.cells):
            if y:
                pieces.append('\r\n')
            for ch, style in row:
                if style != previous:
                    pieces.append(escape_style(style))
                    previous = style
                pieces.append(ch)
        pieces.append('\x1b[0m')
        sys.stdout.write(''.join(pieces))
        sys.stdout.flush()

    def key(self, timeout=.15):
        if not self.buffer:
            if not select.select([0], [], [], timeout)[0]:
                return None
            data = os.read(0, 4096)
            if not data:
                time.sleep(timeout)
                return None
            self.buffer += data
        if self.buffer.startswith(b'\x1b'):
            if self.buffer == b'\x1b' and select.select([0], [], [], .025)[0]:
                self.buffer += os.read(0, 4096)
            seqs = {b'\x1b[A':'up',b'\x1b[B':'down',b'\x1b[C':'right',b'\x1b[D':'left',b'\x1b[Z':'backtab',
                    b'\x1bOP':'f1',b'\x1b[11~':'f1',b'\x1b[1~':'home',b'\x1b[4~':'end',b'\x1b[H':'home',b'\x1b[F':'end',
                    b'\x1b[5~':'pageup',b'\x1b[6~':'pagedown',b'\x1b[3~':'delete',b'\x1bOA':'up',b'\x1bOB':'down',b'\x1bOC':'right',b'\x1bOD':'left'}
            for seq, name in seqs.items():
                if self.buffer.startswith(seq):
                    self.buffer = self.buffer[len(seq):]
                    return name
            mouse = re.match(rb'\x1b\[<(\d+);(\d+);(\d+)([Mm])', self.buffer)
            if mouse:
                self.buffer = self.buffer[mouse.end():]
                return ('mouse', int(mouse[1]), int(mouse[2])-1, int(mouse[3])-1, mouse[4] == b'M')
            other = re.match(rb'\x1b\[[0-9;?]*[a-zA-Z~]', self.buffer)
            if other:
                self.buffer = self.buffer[other.end():]
                return None
            self.buffer = self.buffer[1:]
            return 'escape'
        ch = self.buffer[0]
        if ch >= 128:
            n = 2 if ch < 224 else 3 if ch < 240 else 4
            text = self.buffer[:n].decode('utf-8', 'replace')
            self.buffer = self.buffer[n:]
            return text
        self.buffer = self.buffer[1:]
        return {3:'ctrlc',4:'ctrld',9:'tab',13:'enter',10:'enter',127:'backspace',8:'backspace'}.get(ch, chr(ch))


