class App:
    def __init__(self, conf, journal):
        self.conf, self.journal = conf, journal
        self.today = dt.date.today()
        self.year, self.month = self.today.year, self.today.month
        self.days = [1] * 12
        self.days[self.month-1] = self.today.day
        self.focus = 0
        self.sec_idx, self.tag_idx = 0, 0
        self.mode = 'annual'
        self.scratch_idx, self.scratch_focus = 0, 0
        self.preview_scroll = 0
        self.modal = None
        self.input_text = ''
        self.button = 0
        self.running = True
        self.term = Terminal()
        self.hitboxes = {}
        self.refresh_menus()

    def date(self):
        return self.year, self.month, self.days[self.month-1]

    def refresh_menus(self):
        self.sections, _ = self.journal.menus(self.year)
        self.sec_idx = min(self.sec_idx, len(self.sections))
        sec = self.sections[self.sec_idx-1][0] if self.sec_idx else None
        _, self.tags = self.journal.menus(self.year, sec)
        self.tag_idx = min(self.tag_idx, len(self.tags))

    def event_names(self, month, day):
        return [(g, n) for g, n, m, d in self.conf.events if m == month and d == day]

    def recent_events(self):
        events = defaultdict(list)
        for group, name, month, day in self.conf.events:
            diffs = []
            for year in range(self.today.year-1, self.today.year+2):
                try:
                    date = dt.date(year, month, day)
                    diffs.append((date-self.today).days)
                except ValueError:
                    pass
            if not diffs:
                continue
            diff = min(diffs, key=abs)
            if abs(diff) < self.conf.event_window:
                events[group].append((name, month, day, diff))
        return [(g, sorted(v)) for g, v in sorted(events.items())]

    def draw_menu(self, cv, x, y, w, h, title, values, selected, active, border):
        sty = BASE if active else DIM
        cv.border(x,y,w,h,title,border,sty)
        if h < 3:
            return
        lines = ['<select none>'] + ['%3d │ %s' % (count, name) for name, count in values]
        offset = max(0, min(len(lines)-(h-2), selected-(h-2)//2))
        for row in range(h-2):
            index = offset+row
            if index >= len(lines):
                break
            st = styled(sty, (1 | (32 if active else 0), None, None)) if index == selected else sty
            text = ('> ' if index == selected else '  ') + lines[index]
            cv.text(x+1,y+1+row,text.ljust(w-2),st,w-2)
        self.hitboxes[title.lower()] = (x,y,w,h,offset)

    def markdown(self, cv, x, y, w, h, text, theme='annual', scroll=0):
        colors = self.conf.md[theme]
        in_code = False
        for i, line in enumerate(text.splitlines()[scroll:scroll+h]):
            flags, fg, bg = 0, None, None
            if line.lstrip().startswith('```'):
                in_code = not in_code
                fg = colors['code-fg']
            elif in_code or line.startswith('    '):
                fg = colors['code-fg']
            elif re.match(r'^#{1,6} ', line):
                n = len(line)-len(line.lstrip('#'))
                fg = colors.get('header'+str(n))
                flags |= 1
            elif re.match(r'^\s*([*+-] |\d+\. )',line):
                fg = colors['list']
            elif line.startswith('>'):
                fg = colors['quote']
            cv.text(x, y+i, line, (flags,fg,bg), w)

    def calendar_canvas(self, cols):
        conf = self.conf
        active = self.focus == 2
        dim = BASE if active else DIM
        months = []
        for m in range(1,13):
            weekday, length = calendar.monthrange(self.year,m)
            offset = (weekday+1)%7 if conf.sunday else weekday
            weeks = (offset+length+6)//7
            months.append((offset,length,weeks))
        heights = [max(m[2] for m in months[i:i+cols])+3 for i in range(0,12,cols)]
        cv = Canvas(cols*23, sum(heights))
        selected_box = (0,0,22,7)
        sec = self.sections[self.sec_idx-1][0] if self.sec_idx else None
        tag = self.tags[self.tag_idx-1][0] if self.tag_idx else None
        y = 0
        for row, h in enumerate(heights):
            for col in range(cols):
                m = row*cols+col+1
                if m > 12:
                    break
                offset,length,weeks = months[m-1]
                x = col*23
                cv.border(x,y,23,h,calendar.month_name[m],conf.borders['calendar-month'],dim)
                cv.text(x+1,y+1,' S  M  T  W  T  F  S ' if conf.sunday else ' M  T  W  T  F  S  S ',styled(dim,(8,None,None)))
                extra = 1 if offset == 0 and h-3 > weeks else 0
                for d in range(1,length+1):
                    cell = offset+d-1
                    xx, yy = x+1+(cell%7)*3, y+2+cell//7+extra
                    # Cell padding is deliberately unstyled, as in the terminal date menu.
                    date = (self.year,m,d)
                    entry = self.journal.entries.get(date)
                    st = conf.styles['log-date'] if entry else conf.styles['empty-date']
                    if self.event_names(m,d):
                        st = styled(st,conf.styles['event-date'])
                    wd = (offset+d-1)%7
                    if (wd in (0,6) if conf.sunday else wd in (5,6)):
                        st = styled(st,conf.styles['weekend-date'])
                    selected = False
                    if entry and (sec or tag):
                        sections = entry[2]
                        match = (not sec or sec in sections)
                        if tag:
                            match = match and (tag in sections.get(sec,set()) if sec else any(tag in tags for tags in sections.values()))
                        if match:
                            st = styled(st,conf.styles['highlighted-date'])
                    if date == (self.today.year,self.today.month,self.today.day):
                        st = styled(st,conf.styles['todays-date'])
                    if active and m == self.month and d == self.days[m-1]:
                        st = styled(st,(32,None,None))
                    st = styled(dim,st)
                    val = str(d)
                    cv.text(xx+(2-len(val)),yy,val,st)
                if m == self.month:
                    selected_box = (x,y,x+22,y+h-1)
            y += h
        return cv, selected_box

    def render_annual(self, w, h):
        cv = Canvas(w,h)
        cols = max(1,min(4,w//35))
        cal, box = self.calendar_canvas(cols)
        preferred = 50+cal.width+3
        rw = min(w,max(113,preferred))
        x = max(0,(w-rw)//2)
        deficit = max(0,preferred-rw)
        w1 = 25-(deficit*25//preferred)
        w2 = 25-(deficit*50//preferred-deficit*25//preferred)
        cw = cal.width+2-(deficit-deficit*50//preferred)
        recent = self.recent_events()
        event_rows = sum(1+len(es) for _,es in recent)
        eh = event_rows+2
        main_h = max(cal.height+2,20+eh)
        preview_h = 14
        natural = main_h+preview_h+2
        shrink = max(0,natural-h)
        total = main_h+preview_h+1
        mh = main_h-shrink*main_h//total
        ph = preview_h-(shrink*(main_h+preview_h)//total-shrink*main_h//total)
        fh = 1-(shrink-shrink*(main_h+preview_h)//total)
        ry = max(0,(h-natural)//2)
        m_y = ry+1
        current_events = self.event_names(self.today.month,self.today.day)
        today_extra = ', '.join('%s - %s' % ev for ev in current_events)
        title = 'Today is: %s %s | There are %d log entries for year %d.' % (self.today.strftime('%d. %m. %Y.'), today_extra, len(self.journal.year_entries[self.year]), self.year)
        cv.centered(x,ry,rw,title,(9,None,None))
        left_def = max(0,20+eh-mh)
        menu_h = 20-left_def*20//(20+eh)
        events_h = eh-(left_def-left_def*20//(20+eh))
        self.draw_menu(cv,x,m_y,w1,menu_h,'Sections',self.sections,self.sec_idx,self.focus==0,self.conf.borders['sections-menu'])
        self.draw_menu(cv,x+w1,m_y,w2,menu_h,'Tags',self.tags,self.tag_idx,self.focus==1,self.conf.borders['tags-menu'])
        ey = m_y+menu_h
        cv.border(x,ey,w1+w2,events_h,'Recent & upcoming events (%d)'%sum(len(v) for _,v in recent),self.conf.borders['events-list'],DIM)
        line_y = ey+1
        for group, events in recent:
            if line_y >= ey+events_h-1:
                break
            cv.text(x+1,line_y,group.ljust(max(0,w1+w2-2)),(11,None,None),w1+w2-2)
            line_y += 1
            for name, month, day, diff in events:
                if line_y >= ey+events_h-1:
                    break
                timing = 'today' if diff == 0 else 'in %d days'%diff if diff>0 else '%d days ago'%-diff
                text = ' - %s %02d.%02d. (%s)'%(name,month,day,timing)
                cv.text(x+1,line_y,text,DIM,w1+w2-2)
                line_y += 1
        cx = x+w1+w2
        iw, ih = max(0,cw-2),max(0,mh-2)
        # A focused month, not just the day, drives the framed calendar's scroll.
        sx = max(0,min(cal.width-iw,(box[0]+box[2])//2-(iw-1)//2))
        sy = max(0,min(cal.height-ih,(box[1]+box[3])//2-(ih-1)//2))
        if iw < cal.width and cols == 2:
            sx = min(sx,max(0,(cal.width-iw)*3//4))
        cv.copy(cal,cx+1,m_y+1,sx,sy,iw,ih)
        cv.border(cx,m_y,cw,mh,str(self.year),self.conf.borders['calendar'],BASE if self.focus==2 else DIM)
        self.hitboxes['calendar'] = (cx,m_y,cw,mh,cols,cal,box,sx,sy)
        py = m_y+mh
        cv.border(x,py,rw,ph,kind=self.conf.borders['log-entry-preview'])
        date = self.date()
        date_events = self.event_names(date[1],date[2])
        preview_title = 'log preview for %02d. %02d. %02d.' % (date[2],date[1],date[0]%100)
        if date_events:
            preview_title += '  - ' + ', '.join('%s: %s'%ev for ev in date_events)
        cv.centered(x+1,py+1,rw-2,preview_title)
        item = self.journal.entries.get(date)
        text = item[1] if item else ''
        self.markdown(cv,x+1,py+2,rw-2,max(0,ph-3),text,scroll=self.preview_scroll)
        if fh > 0:
            cv.centered(x,py+ph,rw,'hjkl/arrow keys - navigation | d - delete log | s - see scratchpads | tab - move focus between menus and calendar')
        return cv

    def render_scratch(self,w,h):
        cv = Canvas(w,h)
        box_h = 24
        ry = max(0,(h-27)//3)
        if h < 27:
            box_h = max(2,h-2)
        cv.centered(0,ry,w,'Scratchpad Manager',BOLD)
        cv.text(0,ry+1,'─'*w)
        sy = ry+2
        # The menu has a bounded preferred width, while the preview receives the rest.
        mw = int(30+max(0,w-70)*.12)
        if self.journal.scratch:
            mw += 4
        mw = min(w-8,max(20,mw))
        self.scratch_idx = min(self.scratch_idx,len(self.journal.scratch))
        cv.border(0,sy,mw,box_h,'Scratchpads',self.conf.borders['scratch-menu'])
        cv.border(mw,sy,w-mw,box_h,kind=self.conf.borders['scratch-preview'])
        selected = self.journal.scratch[self.scratch_idx-1] if self.scratch_idx else None
        cv.centered(mw+1,sy+1,w-mw-2,selected[0] if selected else 'Select a scratchpad',BOLD)
        if selected:
            text = self.journal.read(selected[1])
            self.markdown(cv,mw+1,sy+2,w-mw-2,box_h-3,text,'scratch',self.preview_scroll)
        else:
            cv.text(mw+1,sy+2,'No scratchpad selected',width=w-mw-2)
        lines = ['Make new scratchpad'] + [s[0] for s in self.journal.scratch]
        offset = max(0,min(len(lines)-(box_h-2),self.scratch_idx-(box_h-2)//2))
        for row in range(box_h-2):
            index = row+offset
            if index >= len(lines):
                break
            st = (1 | (32 if self.scratch_focus==0 else 0),None,None) if index == self.scratch_idx else BASE
            line = ('> ' if index == self.scratch_idx else '  ')+lines[index]
            if index:
                date = dt.datetime.fromtimestamp(self.journal.scratch[index-1][2]).strftime('%y-%m-%d')
                line = line.ljust(33)+date
            cv.text(1,sy+1+row,line.ljust(mw-2),st,mw-2)
        if sy+box_h < h:
            cv.centered(0,sy+box_h,w,'Press F1 for help.')
        self.hitboxes['scratch'] = (0,sy,mw,box_h,offset)
        return cv

    def render_modal(self,cv):
        w,h = cv.width,cv.height
        if self.modal == 'help':
            mw,mh = min(114,w),min(47,h)
            x,y = max(0,(w-mw)//2),max(0,(h-mh)//2)
            cv.border(x,y,mw,mh,clear=True)
            for j,text in enumerate(HELP_LINES):
                if j+1 >= mh-1:
                    break
                cv.text(x+3,y+1+j,text,width=mw-4)
            if mh >= 47:
                cv.text(x+1,y+mh-5,'─'*(mw-2))
                self.draw_button(cv,x+(mw-7)//2,y+mh-4,'Close',True)
            return
        if self.modal in ('delete-log','delete-scratch'):
            text = 'Are you sure you want to delete a log file?' if self.modal=='delete-log' else 'Are you sure you want to delete a scratchpad?'
            mw,mh = min(w,len(text)+2),7
            x,y = max(0,(w-mw)//2),max(0,(h-mh)//2)
            cv.border(x,y,mw,mh,clear=True)
            cv.text(x+1,y+1,text,width=mw-2)
            cv.text(x+1,y+2,'─'*(mw-2))
            bx = x+(mw-9)//2
            self.draw_button(cv,bx,y+3,'Yes',self.button==0)
            self.draw_button(cv,bx+5,y+3,'No',self.button==1)
            self.hitboxes['buttons'] = (bx,y+3,9,3)
        elif self.modal in ('new-scratch','rename-scratch','password'):
            if self.modal=='new-scratch':
                text = 'Enter the name of the scratchpad to open:'
            elif self.modal=='password':
                text = 'Enter password for encrypted log repository:'
            else:
                name = self.journal.scratch[self.scratch_idx-1][0]
                text = 'Enter the new name for the scratchpad "%s":'%name
            mw,mh = min(w,len(text)+2),8
            x,y = max(0,(w-mw)//2),max(0,(h-mh)//2)
            cv.border(x,y,mw,mh,clear=True)
            cv.text(x+1,y+1,text,width=mw-2)
            cv.text(x+1,y+2,'─'*(mw-2))
            inp = '*'*len(self.input_text) if self.modal=='password' else self.input_text
            cv.text(x+1,y+3,inp[-(mw-2):],(32 if self.button==0 else 0,None,None),mw-2)
            self.draw_button(cv,x+(mw-8)//2,y+4,'Submit',self.button==1)
        else:
            text = str(self.modal)
            mw,mh = min(w,len(text)+2),7
            x,y = max(0,(w-mw)//2),max(0,(h-mh)//2)
            cv.border(x,y,mw,mh,clear=True)
            cv.text(x+1,y+1,text,width=mw-2)
            cv.text(x+1,y+2,'─'*(mw-2))
            self.draw_button(cv,x+(mw-7)//2,y+3,'Close',True)

    def draw_button(self,cv,x,y,label,active):
        st = (32,None,None) if active else BASE
        cv.border(x,y,len(label)+2,3,kind='light',style=st)
        cv.text(x+1,y+1,label,st)

    def open_editor(self,path,template=None):
        existed = os.path.isfile(path)
        ensure_dir(os.path.dirname(path))
        original = self.journal.read(path) if existed else (template or '')
        if not existed or self.journal.encrypted:
            with open(path,'w',encoding='utf-8') as f:
                f.write(original)
        self.term.stop()
        editor = os.environ.get('EDITOR','')
        if not editor:
            editor = 'vi'
        try:
            subprocess.call(editor+' '+shlex.quote(path),shell=True)
        except OSError:
            pass
        if os.path.isfile(path):
            try:
                with open(path,'r',encoding='utf-8',errors='replace') as f:
                    text = f.read()
                if not existed and (text==original or not text):
                    os.unlink(path)
                elif self.journal.encrypted and self.journal.cipher:
                    with open(path,'wb') as f:
                        f.write(self.journal.cipher.apply(text.encode()))
            except OSError:
                pass
        self.term.start()
        self.journal.reload()
        self.refresh_menus()
        self.preview_scroll = 0

    def handle_modal(self,key):
        if key=='ctrlc':
            self.running=False
            return
        if self.modal=='help':
            if key in ('escape','enter','f1','q'):
                self.modal=None
            return
        if self.modal in ('new-scratch','rename-scratch','password'):
            if key=='tab' or key=='backtab':
                self.button = 1-self.button
            elif key=='backspace':
                self.input_text = self.input_text[:-1]
            elif key=='enter':
                kind=self.modal
                name=self.input_text
                self.modal=None
                if kind=='password':
                    self.conf.password=name
                    cipher=Cipher(name)
                    with open(os.path.join(self.conf.log_dir,'.cle'),'rb') as f:
                        valid = cipher.apply(f.read(),True)==b'encryption-marker:'
                    if not valid:
                        raise Failure('Invalid password provided!')
                    self.journal.cipher=cipher
                    self.journal.reload()
                    self.refresh_menus()
                    return
                if not name:
                    return
                if not name.endswith('.md'):
                    name += '.md'
                path=os.path.join(self.journal.scratch_dir,name)
                if kind=='new-scratch':
                    self.open_editor(path,'')
                elif self.scratch_idx:
                    try:
                        os.rename(self.journal.scratch[self.scratch_idx-1][1],path)
                    except OSError as e:
                        self.modal=str(e)
                    self.journal.reload()
                self.scratch_idx=0
            elif isinstance(key,str) and len(key)==1 and ord(key)>=32:
                self.input_text += key
            return
        if self.modal in ('delete-log','delete-scratch'):
            if key in ('tab','backtab','left','right','h','l'):
                self.button=1-self.button
            elif key=='enter':
                mode=self.modal
                self.modal=None
                if self.button==0:
                    if mode=='delete-log':
                        item=self.journal.entries.get(self.date())
                        path=item[0] if item else self.journal.path_for(self.date())
                    else:
                        path=self.journal.scratch[self.scratch_idx-1][1] if self.scratch_idx else ''
                    try:
                        os.unlink(path)
                    except OSError:
                        pass
                    self.journal.reload()
                    self.refresh_menus()
                    self.scratch_idx=0
            return
        if key in ('enter','escape'):
            self.modal=None

    def handle_mouse(self,key):
        _, button, x,y,pressed=key
        if not pressed:
            return
        if button in (64,65):
            self.handle('up' if button==64 else 'down')
            return
        if button!=0:
            return
        if self.modal:
            if self.modal in ('delete-log','delete-scratch'):
                bx,by,bw,bh=self.hitboxes.get('buttons',(0,0,0,0))
                if by<=y<by+bh and bx<=x<bx+bw:
                    self.button=0 if x<bx+5 else 1
                    self.handle_modal('enter')
            return
        if self.mode=='scratch':
            bx,by,bw,bh,offset=self.hitboxes.get('scratch',(0,0,0,0,0))
            if bx<x<bx+bw-1 and by<y<by+bh-1:
                idx=offset+y-by-1
                if idx<=len(self.journal.scratch):
                    self.scratch_idx=idx
                    self.scratch_focus=0
            return
        for key in ('sections','tags'):
            bx,by,bw,bh,offset=self.hitboxes[key]
            if bx<x<bx+bw-1 and by<y<by+bh-1:
                idx=offset+y-by-1
                if key=='sections' and idx<=len(self.sections):
                    self.sec_idx=idx;self.focus=0;self.tag_idx=0;self.refresh_menus()
                elif key=='tags' and idx<=len(self.tags):
                    self.tag_idx=idx;self.focus=1
                return
        bx,by,bw,bh,cols,cal,box,sx,sy=self.hitboxes['calendar']
        if bx<x<bx+bw-1 and by<y<by+bh-1:
            self.focus=2
            px,py=x-bx-1+sx,y-by-1+sy
            try:
                ch=cal.cells[py][px][0]
                if ch.isdigit():
                    start=px
                    if start and cal.cells[py][start-1][0].isdigit():
                        start-=1
                    number=''.join(c[0] for c in cal.cells[py][start:start+2]).strip()
                    if number.isdigit():
                        rowy=0
                        for row in range((12+cols-1)//cols):
                            ms=range(row*cols+1,min(13,(row+1)*cols+1))
                            rh=max(((calendar.monthrange(self.year,m)[0]+(1 if self.conf.sunday else 0))%7+calendar.monthrange(self.year,m)[1]+6)//7 for m in ms)+3
                            if rowy<=py<rowy+rh:
                                self.month=row*cols+px//23+1
                                self.days[self.month-1]=int(number)
                                break
                            rowy+=rh
            except (ValueError,IndexError):
                pass

    def handle(self,key):
        if key is None:
            return
        if isinstance(key,tuple):
            self.handle_mouse(key)
            return
        if self.modal:
            self.handle_modal(key)
            return
        if key in ('q','escape','ctrlc','ctrld'):
            self.running=False
            return
        if key=='f1':
            self.modal='help'
            return
        if key=='s':
            self.mode='scratch' if self.mode=='annual' else 'annual'
            self.preview_scroll=0
            return
        if self.mode=='scratch':
            if key in ('tab','backtab'):
                self.scratch_focus=1-self.scratch_focus
            elif key in ('j','down','k','up'):
                direction=1 if key in ('j','down') else -1
                if self.scratch_focus==0:
                    self.scratch_idx=max(0,min(len(self.journal.scratch),self.scratch_idx+direction))
                    self.preview_scroll=0
                else:
                    self.preview_scroll=max(0,self.preview_scroll+direction)
            elif key=='enter' and self.scratch_focus==0:
                if self.scratch_idx:
                    self.open_editor(self.journal.scratch[self.scratch_idx-1][1])
                else:
                    self.modal='new-scratch';self.input_text='';self.button=0
            elif key=='r' and self.scratch_idx:
                self.modal='rename-scratch';self.input_text='';self.button=0
            elif key=='d' and self.scratch_idx:
                self.modal='delete-scratch';self.button=0
            return
        if key in ('+','-'):
            self.year += 1 if key=='+' else -1
            self.year=max(1,min(9999,self.year))
            self.days=[min(d,calendar.monthrange(self.year,m+1)[1]) for m,d in enumerate(self.days)]
            self.sec_idx=self.tag_idx=0
            self.refresh_menus()
            return
        if key in ('tab','backtab'):
            self.focus=(self.focus+(1 if key=='tab' else -1))%4
            return
        if self.focus in (0,1):
            if key in ('j','down','k','up'):
                direction=1 if key in ('j','down') else -1
                if self.focus==0:
                    old=self.sec_idx
                    self.sec_idx=max(0,min(len(self.sections),self.sec_idx+direction))
                    if self.sec_idx!=old:
                        self.tag_idx=0
                    self.refresh_menus()
                else:
                    self.tag_idx=max(0,min(len(self.tags),self.tag_idx+direction))
            return
        if self.focus==3:
            if key in ('down','j'):
                self.preview_scroll += 1
            elif key in ('up','k'):
                self.preview_scroll=max(0,self.preview_scroll-1)
            return
        if key=='enter':
            date=self.date()
            path=self.journal.entries.get(date,(self.journal.path_for(date),))[0]
            template='# %02d. %02d. %02d.'%(date[2],date[1],date[0]%100)
            self.open_editor(path,template)
        elif key=='d':
            self.modal='delete-log';self.button=0
        elif key in ('left','h','right','l','down','j','up','k'):
            delta={'left':-1,'h':-1,'right':1,'l':1,'down':7,'j':7,'up':-7,'k':-7}[key]
            value=self.days[self.month-1]+delta
            limit=calendar.monthrange(self.year,self.month)[1]
            if value<1:
                self.month=max(1,self.month-1)
            elif value>limit:
                self.month=min(12,self.month+1)
            else:
                self.days[self.month-1]=value
            self.preview_scroll=0

    def run(self):
        def stop(*_):
            self.running=False
        def resize(*_):
            self.term.resized=True
        for sig in (signal.SIGTERM,signal.SIGINT):
            signal.signal(sig,stop)
        signal.signal(signal.SIGWINCH,resize)
        self.term.start()
        if self.journal.encrypted and not self.journal.cipher:
            self.modal='password';self.input_text='';self.button=0
        try:
            dirty=True
            old_size=None
            while self.running:
                size=self.term.size()
                if dirty or size!=old_size or self.term.resized:
                    w,h=size
                    self.hitboxes={}
                    cv=self.render_annual(w,h) if self.mode=='annual' else self.render_scratch(w,h)
                    if self.modal:
                        self.render_modal(cv)
                    self.term.draw(cv)
                    old_size=size
                    self.term.resized=False
                    dirty=False
                key=self.term.key()
                if key is not None:
                    self.handle(key)
                    dirty=True
        finally:
            self.term.stop()


def main():
    try:
        home=os.environ.get('HOME','/home/agent')
        args=parse_args(sys.argv[1:])
        if 'help' in args:
            sys.stdout.write(help_text(home))
            return
        conf=Config(args,home)
        if 'encrypt' in args or 'decrypt' in args:
            decrypt='encrypt' not in args
            if not conf.password:
                raise Failure('Password must be provided when %s logs!'%('decrypting' if decrypt else 'encrypting'))
            apply_crypto(conf,decrypt)
            return
        journal=Journal(conf)
        App(conf,journal).run()
    except Failure as e:
        sys.stderr.write(ERROR+str(e)+'\n')
        sys.exit(1)
    except (OSError,ValueError) as e:
        sys.stderr.write(ERROR+str(e)+'\n')
        sys.exit(1)
    except KeyboardInterrupt:
        pass

if __name__=='__main__':
    main()
